package com.example.library.api.loan;

import com.example.library.application.loan.BorrowBook;
import com.example.library.domain.loan.Isbn;
import com.example.library.domain.loan.LoanId;
import com.example.library.domain.loan.MemberId;
import jakarta.validation.Valid;
import java.net.URI;
import java.util.UUID;
import org.springframework.http.ResponseEntity;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

@RestController
class LoanController {
    private final BorrowBook borrowBook;

    LoanController(BorrowBook borrowBook) {
        this.borrowBook = borrowBook;
    }

    @PostMapping("/loans")
    @Transactional
    ResponseEntity<Void> borrow(@Valid @RequestBody BorrowBookRequest request) {
        LoanId id = new LoanId(UUID.randomUUID());
        borrowBook.execute(id, new MemberId(request.memberId()), new Isbn(request.isbn()));
        return ResponseEntity.created(URI.create("/loans/" + id.value())).build();
    }
}
