package com.example.library.domain.loan;

import java.time.Instant;

public final class Loan {
    public static final int MAX_LOANS_PER_MEMBER = 3;

    private final LoanId id;
    private final MemberId memberId;
    private final Isbn isbn;
    private final Instant borrowedAt;

    private Loan(LoanId id, MemberId memberId, Isbn isbn, Instant borrowedAt) {
        this.id = id;
        this.memberId = memberId;
        this.isbn = isbn;
        this.borrowedAt = borrowedAt;
    }

    public static Loan borrow(LoanId id, MemberId memberId, Isbn isbn, int memberActiveLoans,
                              boolean bookOnLoan, Instant now) {
        if (bookOnLoan) throw new BookAlreadyOnLoanException(isbn);
        if (memberActiveLoans >= MAX_LOANS_PER_MEMBER) throw new LoanLimitReachedException(memberId);
        return new Loan(id, memberId, isbn, now);
    }

    public static Loan restore(LoanId id, MemberId memberId, Isbn isbn, Instant borrowedAt) {
        return new Loan(id, memberId, isbn, borrowedAt);
    }

    public LoanId id() { return id; }
    public MemberId memberId() { return memberId; }
    public Isbn isbn() { return isbn; }
    public Instant borrowedAt() { return borrowedAt; }
}
