package com.example.library.api.loan;

import com.example.library.domain.loan.BookAlreadyOnLoanException;
import com.example.library.domain.loan.LoanLimitReachedException;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
class LoanExceptionHandler {
    @ExceptionHandler({BookAlreadyOnLoanException.class, LoanLimitReachedException.class})
    ProblemDetail conflict(RuntimeException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, e.getMessage());
    }

    @ExceptionHandler(DataIntegrityViolationException.class)
    ProblemDetail raceOnBook(DataIntegrityViolationException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, "Book is already on loan");
    }
}
